import{_ as t,C as s,o as i,c as n,E as r,a2 as o}from"./chunks/framework.Cm6XCzck.js";const k=JSON.parse('{"title":"Open-source Engineering Weekly 002 — Agent Capability Is Being Packaged as Skills, Plugins, and Contracts","description":"","frontmatter":{"title":"Open-source Engineering Weekly 002 — Agent Capability Is Being Packaged as Skills, Plugins, and Contracts","date":"2026-08-02","column":"open-source-engineering","category":"weekly","summary":"OpenHands, CrewAI, AutoGen, and LangGraph show that reusable agent capability is moving from hidden prompt text into explicit skills, plugins, tools, workflows, message contracts, and observable events.","sources":["OpenHands skills and plugins documentation","CrewAI agents, flows, and observability documentation","AutoGen teams, application stack, memory, and logging documentation","LangGraph runtime and human-in-the-loop documentation"],"outline":"deep","cover":"/assets/covers/agent-capability-packaging-cover-v2.jpg"},"headers":[],"relativePath":"en/engineering/2026-08-02-agent-capability-packaging.md","filePath":"en/engineering/2026-08-02-agent-capability-packaging.md","lastUpdated":1787407830000}'),l={name:"en/engineering/2026-08-02-agent-capability-packaging.md"};function d(p,e,c,g,h,u){const a=s("ArticleCover");return i(),n("div",null,[r(a,{image:"/assets/covers/agent-capability-packaging-cover-v2.jpg",kicker:"Open-source Engineering · Weekly 002",title:"Agent Capability Is Being Packaged as Skills, Plugins, and Contracts",summary:"Reusable capability is moving out of hidden prompts and into explicit packages, interfaces, workflow nodes, and events.",version:"EW002",status:"Published 2026-08-02",languageHref:"/zh/engineering/2026-08-02-agent-capability-packaging",languageLabel:"简体中文"}),e[0]||(e[0]=o(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>The second open-source engineering signal is a shift in how agent capability is represented. Early systems often embedded capability inside one long prompt plus an unrestricted tool list. Current systems increasingly package capability as explicit, inspectable components.</p><p>OpenHands uses skills, hooks, MCP configurations, specialized agents, commands, and plugins. CrewAI separates agents, tasks, tools, crews, flows, guardrails, memory, knowledge, and structured outputs. AutoGen separates AgentChat teams from the event-driven Core and requires application-defined message contracts. LangGraph treats nodes, state, edges, interrupts, and persistence as explicit orchestration components.</p><p>The Research Center judgment is:</p><blockquote><p>Reusable agent capability is becoming a governed package with a name, scope, activation rule, interface, version, runtime dependency, event surface, and evidence trail. A prompt fragment alone is not a sufficient skill contract.</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>The selected official sources cover four complementary engineering directions:</p><ol><li><strong>OpenHands Skills and Plugins</strong> — progressive disclosure through <code>SKILL.md</code>, always-on repository context, triggered skills, plugin packages, hooks, MCP servers, agents, and commands.</li><li><strong>CrewAI Agents and Flows</strong> — role-oriented agents, tools, memory, knowledge, structured output, persistent flows, guardrails, callbacks, and observability.</li><li><strong>AutoGen Teams and Core</strong> — team patterns, handoffs, event-driven runtime, message protocols, memory interfaces, state serialization, and structured logging.</li><li><strong>LangGraph orchestration</strong> — explicit state, nodes, transitions, interrupts, persistence, and human decision points.</li></ol><p>These sources reveal engineering patterns. They do not establish one universal standard for skill packaging.</p><h2 id="weekly-highlights" tabindex="-1">Weekly Highlights <a class="header-anchor" href="#weekly-highlights" aria-label="Permalink to &quot;Weekly Highlights&quot;">​</a></h2><h3 id="_1-skills-are-moving-from-prompt-text-to-loadable-artifacts" tabindex="-1">1. Skills are moving from prompt text to loadable artifacts <a class="header-anchor" href="#_1-skills-are-moving-from-prompt-text-to-loadable-artifacts" aria-label="Permalink to &quot;1. Skills are moving from prompt text to loadable artifacts&quot;">​</a></h3><p>OpenHands describes skills as specialized prompts with domain guidance and automated handling, but packages them as files with explicit loading behavior. Always-on context is separated from on-demand skills; keyword or agent-triggered activation supports progressive disclosure. Organization-, user-, and repository-level scopes are distinct.</p><p>This is more operationally useful than copying every instruction into every system prompt.</p><h3 id="_2-plugins-are-becoming-capability-bundles" tabindex="-1">2. Plugins are becoming capability bundles <a class="header-anchor" href="#_2-plugins-are-becoming-capability-bundles" aria-label="Permalink to &quot;2. Plugins are becoming capability bundles&quot;">​</a></h3><p>OpenHands plugins can combine skills, hooks, MCP configuration, specialized agents, and commands. The important engineering change is that a capability package can include both knowledge and runtime integration.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Capability package</span></span>
<span class="line"><span>  ├── Skill instructions</span></span>
<span class="line"><span>  ├── Tool / MCP bindings</span></span>
<span class="line"><span>  ├── Lifecycle hooks</span></span>
<span class="line"><span>  ├── Specialized agent definitions</span></span>
<span class="line"><span>  ├── Commands</span></span>
<span class="line"><span>  └── Versioned package metadata</span></span></code></pre></div><p><em>Diagram: joinwell52 Research Center synthesis from OpenHands plugin documentation.</em></p><h3 id="_3-workflow-systems-are-separating-capability-from-orchestration" tabindex="-1">3. Workflow systems are separating capability from orchestration <a class="header-anchor" href="#_3-workflow-systems-are-separating-capability-from-orchestration" aria-label="Permalink to &quot;3. Workflow systems are separating capability from orchestration&quot;">​</a></h3><p>CrewAI distinguishes agents and their tools from Flows that route, persist, and resume work. LangGraph similarly separates node behavior from state and graph transitions. AutoGen separates agents from team patterns and from the event-driven runtime.</p><p>This allows the same skill or tool to be reused in different workflows without redefining the entire worker.</p><h3 id="_4-message-and-event-contracts-are-becoming-important" tabindex="-1">4. Message and event contracts are becoming important <a class="header-anchor" href="#_4-message-and-event-contracts-are-becoming-important" aria-label="Permalink to &quot;4. Message and event contracts are becoming important&quot;">​</a></h3><p>AutoGen’s application stack requires developers to define message types as a behavior contract. AutoGen also separates trace logs from structured events. This is a strong signal that agent interaction needs machine-readable interfaces, not only conversational text.</p><p>A capability is operationally incomplete when other components cannot determine:</p><ul><li>what input it accepts;</li><li>what output it promises;</li><li>what events it emits;</li><li>what errors or holds it can return;</li><li>what authority it requires;</li><li>how it is versioned.</li></ul><h2 id="cross-analysis" tabindex="-1">Cross Analysis <a class="header-anchor" href="#cross-analysis" aria-label="Permalink to &quot;Cross Analysis&quot;">​</a></h2><h3 id="capability-representation-matrix" tabindex="-1">Capability representation matrix <a class="header-anchor" href="#capability-representation-matrix" aria-label="Permalink to &quot;Capability representation matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dimension</th><th>OpenHands</th><th>CrewAI</th><th>AutoGen</th><th>LangGraph</th></tr></thead><tbody><tr><td>Primary capability unit</td><td>Skill / plugin / agent / command</td><td>Agent / tool / task / crew</td><td>Agent / team / message handler</td><td>Node / runnable / graph</td></tr><tr><td>Activation</td><td>Always-on, user-triggered, keyword or agent-selected</td><td>Task/process/flow invocation</td><td>Runtime messages, team selection, handoff</td><td>Edge, condition, interrupt, command</td></tr><tr><td>Tool integration</td><td>Plugin and MCP configuration</td><td>Agent tools and integration tools</td><td>Tool-capable agents and extensions</td><td>Tool nodes and application code</td></tr><tr><td>State</td><td>Conversation and workspace context</td><td>Flow and crew state</td><td>Agent/team state and memory protocol</td><td>Explicit graph state and checkpoints</td></tr><tr><td>Interface contract</td><td>Skill format and plugin structure</td><td>Structured task inputs/outputs and Pydantic models</td><td>Message protocol and event types</td><td>State schema and node transition contract</td></tr><tr><td>Observability</td><td>Runtime/plugin logs and hooks</td><td>Traces, callbacks, monitoring</td><td>Trace and structured event loggers</td><td>State history and tracing integration</td></tr><tr><td>Distribution</td><td>Registry/repository packages</td><td>Project packages and managed platform</td><td>Python components and distributed runtime</td><td>Libraries, deployment, and runtime services</td></tr></tbody></table><p><strong>Note:</strong> This comparison describes documented abstractions, not feature parity or quality.</p><h3 id="proposed-minimum-skill-contract" tabindex="-1">Proposed minimum Skill Contract <a class="header-anchor" href="#proposed-minimum-skill-contract" aria-label="Permalink to &quot;Proposed minimum Skill Contract&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">skill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  purpose</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  activation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  input_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  output_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed_tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  required_authority</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  runtime_dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  emitted_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  failure_states</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_requirements</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>This is a Research Center synthesis, not a frozen product schema.</p><h2 id="new-architecture-judgment" tabindex="-1">New Architecture Judgment <a class="header-anchor" href="#new-architecture-judgment" aria-label="Permalink to &quot;New Architecture Judgment&quot;">​</a></h2><ol><li><strong>Skill should be an explicit artifact.</strong> Hidden prompt content cannot be reliably discovered, versioned, activated, or audited.</li><li><strong>Capability and workflow should be separate.</strong> A skill describes what can be done; a workflow determines when and in what sequence it is used.</li><li><strong>A plugin may bind knowledge to runtime infrastructure.</strong> This is powerful but expands the security and review boundary.</li><li><strong>Message and event contracts are necessary for multi-agent composition.</strong> Free-form text alone is insufficient for dependable orchestration.</li><li><strong>Activation state must be observable.</strong> Installed, loaded, selected, executed, and verified are different states.</li></ol><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>This report does not change TMPA publications. As research input, it supports explicit references among Role, Authority, Message, Event, Lifecycle, and Integrity for capability activation and execution.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>A Digital Employee should own a governed capability catalog. Each skill should have scope, version, owner, authority requirements, runtime bindings, evidence expectations, and evaluation history.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu currently loads skills and exposes tool usage, but the product should distinguish:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>available</span></span>
<span class="line"><span>→ installed</span></span>
<span class="line"><span>→ activated</span></span>
<span class="line"><span>→ invoked</span></span>
<span class="line"><span>→ completed</span></span>
<span class="line"><span>→ verified</span></span></code></pre></div><p>The Runtime should record which version of a skill was active for each WorkOrder and which structured events and evidence were produced.</p><h2 id="next-week-research" tabindex="-1">Next Week Research <a class="header-anchor" href="#next-week-research" aria-label="Permalink to &quot;Next Week Research&quot;">​</a></h2><ol><li>Compare AgentSkills, Claude Code plugins, MCP servers, and framework-specific tools.</li><li>Define a portable Skill Contract for CodeFlowMu.</li><li>Examine signature, trust, and permission models for third-party capability packages.</li><li>Test whether one skill can operate consistently across different Agent providers.</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>OpenHands, <strong>Skills overview</strong>: <a href="https://docs.openhands.dev/overview/skills" target="_blank" rel="noreferrer">https://docs.openhands.dev/overview/skills</a></li><li>OpenHands, <strong>Organization and User Skills</strong>: <a href="https://docs.openhands.dev/overview/skills/org" target="_blank" rel="noreferrer">https://docs.openhands.dev/overview/skills/org</a></li><li>OpenHands, <strong>Adding New Skills</strong>: <a href="https://docs.openhands.dev/overview/skills/adding" target="_blank" rel="noreferrer">https://docs.openhands.dev/overview/skills/adding</a></li><li>OpenHands, <strong>Plugins</strong>: <a href="https://docs.openhands.dev/sdk/guides/plugins" target="_blank" rel="noreferrer">https://docs.openhands.dev/sdk/guides/plugins</a></li><li>CrewAI, <strong>Documentation</strong>: <a href="https://docs.crewai.com/" target="_blank" rel="noreferrer">https://docs.crewai.com/</a></li><li>CrewAI, <strong>CrewAI AMP</strong>: <a href="https://docs.crewai.com/enterprise/introduction" target="_blank" rel="noreferrer">https://docs.crewai.com/enterprise/introduction</a></li><li>Microsoft AutoGen, <strong>Teams</strong>: <a href="https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/tutorial/teams.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/tutorial/teams.html</a></li><li>Microsoft AutoGen, <strong>Application Stack</strong>: <a href="https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/core-concepts/application-stack.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/core-concepts/application-stack.html</a></li><li>Microsoft AutoGen, <strong>Memory and RAG</strong>: <a href="https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/memory.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/memory.html</a></li><li>Microsoft AutoGen, <strong>Logging</strong>: <a href="https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/framework/logging.html" target="_blank" rel="noreferrer">https://microsoft.github.io/autogen/stable/user-guide/core-user-guide/framework/logging.html</a></li><li>LangChain, <strong>LangGraph overview</strong>: <a href="https://docs.langchain.com/oss/python/langgraph/overview" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/langgraph/overview</a></li></ol>`,46))])}const b=t(l,[["render",d]]);export{k as __pageData,b as default};
